package com.groupvm.catalog.application;
import com.groupvm.catalog.application.command.CreateProductCommand; import com.groupvm.catalog.application.exception.*; import com.groupvm.catalog.infra.ProductRepository; import org.junit.jupiter.api.*; import java.math.BigDecimal; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class ProductServiceTest { private ProductRepository repo; private ProductService service; @BeforeEach void setUp(){repo=mock(ProductRepository.class);service=new ProductService(repo);} @Test void createsWhenSkuIsAvailable(){when(repo.existsBySku("A")).thenReturn(false);when(repo.save(any())).thenAnswer(i->i.getArgument(0));var p=service.create(new CreateProductCommand("A","A",null,BigDecimal.TEN));assertEquals("A",p.getSku());verify(repo).save(any());} @Test void rejectsDuplicateSku(){when(repo.existsBySku("A")).thenReturn(true);assertThrows(DuplicateSkuException.class,()->service.create(new CreateProductCommand("A","A",null,BigDecimal.TEN)));verify(repo,never()).save(any());} @Test void missingProductIsNotFound(){when(repo.findById(any())).thenReturn(Optional.empty());assertThrows(ProductNotFoundException.class,()->service.get(UUID.randomUUID()));} }
